import axios from 'axios'
import { successHandle, failHandle, defineUnsupportedProps } from '../../../common/js'
import RequestTask from './RequestTask'
import { serialize, buildUrl } from '@mpxjs/utils'

function request (options = { url: '' }) {
  const CancelToken = axios.CancelToken
  const source = CancelToken.source()
  const requestTask = new RequestTask(source.cancel)

  let {
    url,
    data = {},
    method = 'GET',
    dataType = 'json',
    responseType = 'text',
    timeout = global.__networkTimeout || 60 * 1000,
    header = {},
    success = null,
    fail = null,
    complete = null
  } = options
  method = method.toUpperCase()
  if (method === 'GET') {
    url = buildUrl(url, data)
    data = {}
  }

  if (
    method === 'POST' &&
    typeof data !== 'string' && // string 不做处理
    (header['Content-Type'] === 'application/x-www-form-urlencoded' ||
      header['content-type'] === 'application/x-www-form-urlencoded')
  ) {
    data = serialize(data)
  }

  /**
   * axios 的其他参数
   * baseURL
   * transformRequest
   * transformResponse,
   * headers,
   * params,
   * paramsSerializer,
   * withCredentials,
   * adapter,
   * auth,
   * xsrfCookieName,
   * xsrfHeaderName,
   * onUploadProgress,
   * onDownloadProgress,
   * maxContentLength,
   * maxBodyLength,
   * validateStatus,
   * maxRedirects,
   * socketPath,
   * httpAgent,
   * httpsAgent,
   * decompress
   */
  const rOptions = Object.assign(options, {
    method,
    url,
    data,
    headers: header,
    responseType,
    timeout,
    cancelToken: source.token,
    transitional: {
      // silent JSON parsing mode
      // `true`  - ignore JSON parsing errors and set response.data to null if parsing failed (old behaviour)
      // `false` - throw SyntaxError if JSON parsing failed (Note: responseType must be set to 'json')
      silentJSONParsing: true, // default value for the current Axios version
      // try to parse the response string as JSON even if `responseType` is not 'json'
      forcedJSONParsing: false,
      // throw ETIMEDOUT error instead of generic ECONNABORTED on request timeouts
      clarifyTimeoutError: false
    }
  })
  if (method === 'GET') {
    rOptions.params = rOptions.data || {}
    delete rOptions.data
  }
  axios(rOptions).then(res => {
    let data = res.data
    if (dataType === 'json' && typeof data === 'string') {
      try {
        data = JSON.parse(data)
      } catch (e) {
      }
    }

    const result = Object.assign({}, res, {
      errMsg: 'request:ok',
      data,
      statusCode: res.status,
      header: res.headers
    })
    defineUnsupportedProps(result, ['cookies', 'profile', 'exception'])
    successHandle(result, success, complete)
    return result
  }).catch(err => {
    const realError = err || {}
    const response = realError.response || {}
    const res = {
      errMsg: `request:fail ${err}`,
      statusCode: response.status,
      header: response.headers,
      data: response.data
    }
    Object.assign(res, realError)
    failHandle(res, fail, complete)
  })

  return requestTask
}

export {
  request
}
class RequestTask {
  constructor (abortCb) {
    this._abortCb = abortCb
  }

  abort () {
    if (typeof this._abortCb === 'function') {
      this._abortCb()
    }
  }
}

export default RequestTask

# 跨平台环境 API {#api-proxy}

Mpx 生态提供的一套跨平台环境 API 的抹平，方便开发者在开发跨平台应用时，使用相同的代码访问跨平台一致的环境 API 能力，目前已支持的平台包括微信、支付宝等主流小程序平台、Web 和 React Native。

已完成跨平台适配的环境 API 均会在官方文档中提供详细说明。若您在文档中未找到某个环境 API 的相关介绍，说明该 API 尚未进行跨平台适配。

如果你的应用只需要输出到小程序，而无需跨平台，你可以参考对应小程序平台的官方文档直接调用对应的环境 API，即使该 API 未在当前文档中列出。

## 使用 {#usage}

```js
// 使用 Mpx 生态

import mpx from "@mpxjs/core"
import apiProxy from "@mpxjs/api-proxy"

mpx.use(apiProxy, options)
```

## 配置项 (Options) {#options}

所有配置均为可选，可根据实际需求组合使用

| 参数名称        | 类型              | 含义                                                       | 是否必填 | 默认值  | 备注                                                        |
| --------------- | ----------------- | ---------------------------------------------------------- | -------- | ------- | ----------------------------------------------------------- |
| ~~platform~~    | ~~Object~~        | ~~各平台之间的转换~~                                       | ~~否~~   |         | 已删除                                                      |
| ~~exclude~~     | ~~Array(String)~~ | ~~跨平台时不需要转换的 api~~                               | ~~否~~   | ~~[]~~  | 已删除                                                      |
| usePromise      | Boolean           | 是否启用 Promise 化风格调用                                | 否       | `false` | 开启后，符合 Promise 化规则的异步 API 会返回 Promise 对象   |
| whiteList       | Array(String)     | **强制启用** Promise 化的 API 名单                         | 否       | `[]`    | 仅在 usePromise: true 时有效，可覆盖 blackList              |
| blackList       | Array(String)     | **强制禁用** Promise 化的 API 名单                         | 否       | `[]`    | 即使在 usePromise: true 时，名单内的 API 也不会返回 Promise |
| ~~fallbackMap~~ | ~~Object~~        | ~~对于不支持的 API，允许配置一个映射表，接管不存在的 API~~ | ~~否~~   | ~~{}~~  | 已删除                                                      |
| custom          | Object            | 提供用户在各渠道下自定义 api 开放能力                      | 否       | `[]`    | 用于扩展或自定义特定平台下的 API 实现                       |

## 使用介绍 {#introduction}

### 普通形式 {#normal-form}

```js
import mpx from "@mpxjs/core"
import apiProxy from "@mpxjs/api-proxy"

mpx.use(apiProxy)

mpx.showModal({
  title: "标题",
  content: "这是一个弹窗",
  success(res) {
    if (res.cancel) {
      console.log("用户点击取消")
    }
  },
})
```

### usePromise

启用 `usePromise` 选项后，在 Promise 化规则范围内的异步 `API` 会返回 `Promise` 对象。部分小程序 `API`（如 `uploadFile`）的返回值本身具有特定意义（例如返回一个 `uploadTask` 对象用于监听上传进度或取消任务）。为了兼容这种情况，这些 `API` 的原始返回值会被挂载到返回的 `Promise` 对象的 `__returned` 属性上，开发者仍可正常访问和使用。

> [!important] ⚠️ 注意
>
> - **与原生微信小程序差异**
>   - 在 `Mpx` 中，开启 `usePromise` 后，在 Promise 化规则范围内的异步 `API` 会返回 `Promise`，统一支持 `await` 或 `.then()` 语法（部分 API 因语义或命名规则默认不参与 Promise 化，见下文「whiteList 与 blackList」）。
>   - 而微信小程序原生环境中则存在差异：大部分接收 `success` 和 `fail` 回调的 `API` 已支持 `Promise` 化写法，**但存在个别特例——** 这些 `API` 虽然同样接收 `success` 和 `fail` 参数，却不支持 `promisify` 风格调用。
> - **混用风险**
>   - API 调用同时支持 `success/fail` 回调与 `Promise` 的 `then/catch` 写法，且两者两种方式可以共存使用。虽然支持共存，但还是**强烈建议开启 `usePromise` 后，支持 `promisify` 风格的 `API` 都走 `then/catch` 写法**以避免产生下面提示的第三项的影响
>   - 当同时使用时，若调用成功，`success` 回调与 `then` 方法会依次执行；若调用失败，`fail` 回调与 `catch` 方法会依次执行。
>   - 需注意：若仅使用了 `success/fail` 回调（未搭配 `then/catch`），当 API 调用失败时，由于没有 `catch` 捕获异常，会触发 `onUnhandledRejection` 事件。
> - **临时关闭 Promise 转换**
>   - 如仍需在某次调用中使用 `success/fail` 回调，且不希望触发因未捕获 `Promise` 错误而产生的警告，可通过传入 `usePromise: false` 选项临时关闭本次调用的 `Promise` 转换（默认为 `true`）。

```js
import mpx from "@mpxjs/core"
import apiProxy from "@mpxjs/api-proxy"

// 启用 Promise 风格
mpx.use(apiProxy, {
  usePromise: true,
  blackList: ["getSystemInfo"],
})

// 加入黑名单后，需要以 success/fail 方式调用
mpx.getSystemInfo({
  success(res) {
    console.log(res, "getSystemInfo success")
  },
  fail(err) {
    console.log(err, "getSystemInfo error")
  },
})
```

### whiteList 与 blackList {#whitelist-and-blacklist}

在 `usePromise: true` 时，除你在 `whiteList` / `blackList` 中的配置外，实现里还会按命名与语义过滤一部分 **默认不** 做 Promise 化的方法，例如：

- 名称以 `Sync` 结尾的同步风格 API；
- 名称以 `on`、`off` 开头的监听类 API；
- 名称匹配 `get*Manager` 的 API；
- 名称匹配 `create*` 的 API（`createBLEConnection`、`createBLEPeripheralServer` 等少数例外会参与 Promise 化）；
- 另有少量特殊 API（如 `nextTick`、`canIUse`、部分信息获取类方法等）在实现中固定不参与 Promise 化。
