<script>
import mpx, { createPage } from '@mpxjs/core'
import { fetchTrendingKeywords, requestSuggestions } from '../../services/search'

createPage({
  data: {
    keyword: '',
    trendingKeywords: [],
    suggestions: [],
    requestTask: null
  },
  async onLoad () {
    this.trendingKeywords = await fetchTrendingKeywords()
  },
  onUnload () {
    this.cancelSuggestions()
  },
  methods: {
    onKeywordInput (event) {
      this.search(event.detail.value.trim())
    },
    chooseKeyword (keyword) {
      this.search(keyword)
    },
    cancelSuggestions () {
      const requestTask = this.requestTask
      this.requestTask = null
      if (requestTask) requestTask.abort()
    },
    search (keyword) {
      this.keyword = keyword
      this.cancelSuggestions()
      if (!keyword) {
        this.suggestions = []
        return
      }
      let requestTask
      requestTask = requestSuggestions(keyword, {
        success: ({ data }) => {
          if (this.requestTask !== requestTask || this.keyword !== keyword) return
          this.requestTask = null
          this.suggestions = data.list
        },
        fail: () => {
          if (this.requestTask !== requestTask || this.keyword !== keyword) return
          this.requestTask = null
          mpx.showToast({
            title: '搜索失败',
            icon: 'none'
          }).catch(() => {})
        }
      })
      this.requestTask = requestTask
    },
    openProduct (productId) {
      mpx.navigateTo({
        url: `/pages/product/detail?id=${productId}`
      }).catch(() => {})
    }
  }
})
</script>

